window.AUTH=window.AUTH||{};window.AUTH["18-587"]={"d":"18-587","id":"2019/18-587","n":"Department of Homeland Security v. Regents of the University of California","briefs":[{"k":"petitioner","label":"Brief of petitioners Department of Homeland Security, et al.","date":"2019-08-19","url":"https://www.supremecourt.gov/DocketPDF/18/18-587/112855/20190819213105900_18-587tsUnitedStates.pdf","side":"pet","n":56},{"k":"respondent","label":"Brief of respondents States of California, et al.","date":"2019-09-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-587/117278/20190927114833400_No.%2018-587%20DHS%20v.%20Regents%20-%20Brief%20of%20States%20of%20California%20et%20al.%20FINAL%20PDFA.pdf","side":"res","n":11},{"k":"respondent","label":"Brief of respondents Regents of the University of California, et al.","date":"2019-09-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-587/117328/20190927151220415_18-587%20Regents%20Brief%20for%20Respondents.pdf","side":"res","n":55},{"k":"respondent","label":"Brief of respondents New York, et al.","date":"2019-09-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-587/117394/20190927213845015_18-589_Br%20for%20Resp%20States%20of%20NY%20et%20al.pdf","side":"res","n":42},{"k":"respondent","label":"Brief of respondents DACA Recipients, et al.","date":"2019-09-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-587/117313/20190927141141600_DACA%20Merits%20Brief%20TO%20FILE.pdf","side":"res","n":80},{"k":"reply","label":"Reply of petitioners Department of Homeland Security, et al.","date":"2019-10-28","url":"https://www.supremecourt.gov/DocketPDF/18/18-587/120561/20191028212351841_18-587rbUnitedStates.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US1PP_web.pdf#page=11","tr":true,"items":[{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"4, 20, 45","3":"38,44,50","4":"3, 39, 44"}},{"t":"case","label":"Bowman Transp., Inc. v. Arkansas-Best Freight Sys., Inc.","cite":"419 U.S. 281","y":1974,"id":"1974/73-1055","sc":1,"sum":"The Supreme Court held that the ICC based its decisions on consideration of relevant factors. While the ICC could have explained its reasoning more clearly, the Court did not feel the decisions were arbitrary and capricious. The Court also remanded the case to determine whether Bowman should receive the excess authority the ICC granted.","sumSrc":"Oyez","by":{"0":"27","4":"30, 33"}},{"t":"case","label":"Casa de Maryland v. DHS","cite":"924 F.3d 684","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/924/684/","op":2,"by":{"0":"19, 22, 24","2":"13","3":"13,19,20","5":"8"}},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32, 37, 43","2":"passim","3":"passim","4":"passim","5":"3, 6, 23"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"136 S. Ct. 2117","y":2016,"id":"2015/15-415","sc":1,"op":1,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"0":"51","2":"32, 33, 41, 43","3":"40,41","4":"30, 34"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"op":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"44, 45, 48","2":"52"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"op":6,"sum":"They are presumptively unreviewable. Refusals of administrative agencies to exercise enforcement authority involve a complicated balancing of factors, including agency allocation of scarce resources, which are not suitable for judicial review. Thus, they are presumptively \"committed to agency discretion by law\" under Section 701(a)(2).","sumSrc":"Oyez","by":{"0":"passim","2":"passim","3":"passim","4":"19, 20, 22","5":"7, 9, 10, 12"}},{"t":"case","label":"ICC v. Brotherhood of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"op":1,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 23, 24","2":"19, 24, 25","3":"27,28","4":"23, 25","5":"9, 10"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"21","2":"18","3":"22","4":"17","5":"12"}},{"t":"case","label":"International Union v. Brock","cite":"783 F.2d 237","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/783/237/","by":{"0":"26","2":"20, 24"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"op":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"21","3":"30","4":"28, 29"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"op":1,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","2":"19"}},{"t":"case","label":"Martin v. OSHRC","cite":"499 U.S. 144","y":1991,"id":"1990/89-1541","sc":1,"sum":"A reviewing court should defer to the Secretary when the Secretary and the Commission furnish reasonable but conflicting interpretations of an ambiguous regulation promulgated by the Secretary under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","3":"21"}},{"t":"case","label":"Morgan Stanley Capital Grp. Inc. v. Public Util. Dist. No. 1","cite":"554 U.S. 527","y":2008,"id":"2007/06-1457","sc":1,"op":1,"sum":"Renegotiation is allowed only if the contract poses \"serious harm to the public interest.\" In this case, the Court decided 5-2 (Justices John G. Roberts and Stephen Breyer took no part in the decision) that the Federal Energy Regulatory Commission had failed to make sufficient factual findings in order to determine whether such serious harm could in fact occur.","sumSrc":"Oyez","by":{"0":"51","5":"6"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"op":10,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"29, 35, 50","2":"passim","3":"passim","4":"37, 48","5":"17, 20"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"op":5,"sum":"Holding that “an alien unlawfully in this country has no constitutional right to assert selective enforcement as a defense against his deportation”.","sumSrc":"opinion","by":{"0":"passim","2":"26, 45, 52","3":"passim","4":"5, 28, 29, 40, 41, 45","5":"10, 22"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"op":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50","2":"20, 31, 44","3":"21,35","4":"29, 48"}},{"t":"case","label":"Texas v. United States: 86 F. Supp. 3d 591 (S.D. Tex.), aff ’d","cite":"809 F.3d 134","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/134/","op":12,"sum":"Noting Palinkas’s claim that “DACA applications are simply rubberstamped if the applicants meet the necessary criteria” (quotation marks omitted).","sumSrc":"brief:3","by":{"0":"6","2":"8, 23, 33, 34, 47","3":"passim","4":"8, 21, 32, 44, 51, 52"}},{"t":"case","label":"Texas v. United States","cite":"328 F. Supp. 3d 662","y":2018,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/328/662/","op":2,"by":{"0":"34","2":"54","3":"32,33","4":"52"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"32","4":"25, 43, 54"}},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held that in order to file selective-prosecution claims, defendants must show that the government failed to prosecute similarly situated suspects of other races. \"If the claim . . . were well founded,\" wrote Rehnquist, \"it should not have been an insuperable task to prove that persons of a different race were not prosecuted.\".","sumSrc":"Oyez","by":{"0":"19, 30","4":"42","5":"10"}},{"t":"case","label":"United States v. Texas","cite":"136 S. Ct. 2271","y":2016,"id":"2015/15-674","sc":1,"sum":"A case in which the equally divided Court affirmed the lower court's judgment that the Deferred Action for Parents of Americans and Lawful Permanent Residents (DAPA) program was arbitrary and capricious, and failed to undergo notice-and-comment procedures as required by the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"op":4,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"45","2":"52","4":"40","5":"19"}},{"t":"case","label":"Village of Arlington Heights v. Metropolitan Hous. Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"op":5,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"0":"53","3":"53,54"}},{"t":"case","label":"Wayte v. United States","cite":"470 U.S. 598","y":1985,"id":"1984/83-1292","sc":1,"op":2,"sum":"The Supreme Court held, 7-to-2, that the government's passive enforcement policy was constitutional.","sumSrc":"Oyez","by":{"0":"22","4":"42"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53","2":"19"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"6"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"17, 17","1":"23","2":"passim","4":"18, 14, 18","5":"4, 9, 10, 12"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)","(2)(C)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"17","2":"passim","4":"10, 16, 27, 29, 47, 27","5":"6, 12"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","by":{"0":"17"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(27)(J)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"3","1":"32","5":"11"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(1)","(a)(2)","(a)(3)"],"stext":{"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","paras":[[0,"(a) Secretary of Homeland Security"],[0,"(1) The Secretary of Homeland Security shall be charged with the administration and enforcement of this chapter and all other laws relating to the immigration and naturalization of aliens, except insofar as this chapter or such laws relate to the powers, functions, and duties conferred upon the President, Attorney General, the Secretary of State, the officers of the Department of State, or diplomatic or consular officers: Provided, however, That determination and ruling by the Attorney General with respect to all questions of law shall be controlling."],[0,"(2) He shall have control, direction, and supervision of all employees and of all the files and records of the Service."],[0,"(3) He shall establish such regulations; prescribe such forms of bond, reports, entries, and other papers; issue such instructions; and perform such other acts as he deems necessary for carrying out his authority under the provisions of this chapter."],[0,"(4) He may require or authorize any employee of the Service or the Department of Justice to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon any other employee of the Service."],[0,"(5) He shall have the power and duty to control and guard the boundaries and borders of the United States against the illegal entry of aliens and shall, in his discretion, appoint for that purpose such number of employees of the Service as to him shall appear necessary and proper."],[0,"(6) He is authorized to confer or impose upon any employee of the United States, with the consent of the head of the Department or other independent establishment under whose jurisdiction the employee is serving, any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(7) He may, with the concurrence of the Secretary of State, establish offices of the Service in foreign countries; and, after consultation with the Secretary of State, he may, whenever in his judgment such action may be necessary to accomplish the purposes of this chapter, detail employees of the Service for duty in foreign countries."],[0,"(8) After consultation with the Secretary of State, the Attorney General may authorize officers of a foreign country to be stationed at preclearance facilities in the United States for the purpose of ensuring that persons traveling from or through the United States to that foreign country comply with that country's immigration and related laws."],[0,"(9) Those officers may exercise such authority and perform such duties as United States immigration officers are authorized to exercise and perform in that foreign country under reciprocal agreement, and they shall enjoy such reasonable privileges and immunities necessary for the performance of their duties as the government of their country extends to United States immigration officers."],[0,"(10) In the event the Attorney General determines that an actual or imminent mass influx of aliens arriving off the coast of the United States, or near a land border, presents urgent circumstances requiring an immediate Federal response, the Attorney General may authorize any State or local law enforcement officer, with the consent of the head of the department, agency, or establishment under whose jurisdiction the individual is serving, to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(11) The Attorney General, in support of persons in administrative detention in non-Federal institutions, is authorized—"],[1,"(A) to make payments from funds appropriated for the administration and enforcement of the laws relating to immigration, naturalization, and alien registration for necessary clothing, medical care, necessary guard hire, and the housing, care, and security of persons detained by the Service pursuant to Federal law under an agreement with a State or political subdivision of a State; and"],[1,"(B) to enter into a cooperative agreement with any State, territory, or political subdivision thereof, for the necessary construction, physical renovation, acquisition of equipment, supplies or materials required to establish acceptable conditions of confinement and detention services in any State or unit of local government which agrees to provide guaranteed bed space for persons detained by the Service."],[0,"(b) Land acquisition authority"],[0,"(1) The Attorney General may contract for or buy any interest in land, including temporary use rights, adjacent to or in the vicinity of an international land border when the Attorney General deems the land essential to control and guard the boundaries and borders of the United States against any violation of this chapter."],[0,"(2) The Attorney General may contract for or buy any interest in land identified pursuant to paragraph (1) as soon as the lawful owner of that interest fixes a price for it and the Attorney General considers that price to be reasonable."],[0,"(3) When the Attorney General and the lawful owner of an interest identified pursuant to paragraph (1) are unable to agree upon a reasonable price, the Attorney General may commence condemnation proceedings pursuant to section 3113 of title 40."],[0,"(4) The Attorney General may accept for the United States a gift of any interest in land identified pursuant to paragraph (1)."],[0,"(c) Commissioner; appointment"],[0,"The Commissioner shall be a citizen of the United States and shall be appointed by the President, by and with the advice and consent of the Senate. He shall be charged with any and all responsibilities and authority in the administration of the Service and of this chapter which are conferred upon the Attorney General as may be delegated to him by the Attorney General or which may be prescribed by the Attorney General. The Commissioner may enter into cooperative agreements with State and local law enforcement agencies for the purpose of assisting in the enforcement of the immigration laws."],[0,"(d) Statistical information system"],[0,"(1) The Commissioner, in consultation with interested academicians, government agencies, and other parties, shall provide for a system for collection and dissemination, to Congress and the public, of information (not in individually identifiable form) useful in evaluating the social, economic, environmental, and demographic impact of immigration laws."],[0,"(2) Such information shall include information on the alien population in the United States, on the rates of naturalization and emigration of resident aliens, on aliens who have been admitted, paroled, or granted asylum, on nonimmigrants in the United States (by occupation, basis for admission, and duration of stay), on aliens who have not been admitted or have been removed from the United States, on the number of applications filed and granted for cancellation of removal, and on the number of aliens estimated to be present unlawfully in the United States in each fiscal year."],[0,"(3) Such system shall provide for the collection and dissemination of such information not less often than annually."],[0,"(e) Annual report"],[0,"(1) The Commissioner shall submit to Congress annually a report which contains a summary of the information collected under subsection (d) and an analysis of trends in immigration and naturalization."],[0,"(2) Each annual report shall include information on the number, and rate of denial administratively, of applications for naturalization, for each district office of the Service and by national origin group."],[0,"(f) Minimum number of agents in States"],[0,"The Attorney General shall allocate to each State not fewer than 10 full-time active duty agents of the Immigration and Naturalization Service to carry out the functions of the Service, in order to ensure the effective enforcement of this chapter."],[0,"(g) Attorney General"],[0,"(1) In general"],[1,"The Attorney General shall have such authorities and functions under this chapter and all other laws relating to the immigration and naturalization of aliens as were exercised by the Executive Office for Immigration Review, or by the Attorney General with respect to the Executive Office for Immigration Review, on the day before the effective date of the Immigration Reform, Accountability and Security Enhancement Act of 2002."],[0,"(2) Powers"],[1,"The Attorney General shall establish such regulations, prescribe such forms of bond, reports, entries, and other papers, issue such instructions, review such administrative determinations in immigration proceedings, delegate such authority, and perform such other acts as the Attorney General determines to be necessary for carrying out this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1103?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","tname":"Aliens and Nationality","by":{"0":"44, 44, 44","2":"16","4":"21, 39","5":"11"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)","(b)(1)(A)"],"stext":{"head":"§1158. Asylum","paras":[[0,"(a) Authority to apply for asylum"],[0,"(1) In general"],[1,"Any alien who is physically present in the United States or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters), irrespective of such alien's status, may apply for asylum in accordance with this section or, where applicable, section 1225(b) of this title."],[0,"(2) Exceptions"],[0,"(A) Safe third country"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that the alien may be removed, pursuant to a bilateral or multilateral agreement, to a country (other than the country of the alien's nationality or, in the case of an alien having no nationality, the country of the alien's last habitual residence) in which the alien's life or freedom would not be threatened on account of race, religion, nationality, membership in a particular social group, or political opinion, and where the alien would have access to a full and fair procedure for determining a claim to asylum or equivalent temporary protection, unless the Attorney General finds that it is in the public interest for the alien to receive asylum in the United States."],[0,"(B) Time limit"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien unless the alien demonstrates by clear and convincing evidence that the application has been filed within 1 year after the date of the alien's arrival in the United States."],[0,"(C) Previous asylum applications"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien if the alien has previously applied for asylum and had such application denied."],[0,"(D) Changed circumstances"],[2,"An application for asylum of an alien may be considered, notwithstanding subparagraphs (B) and (C), if the alien demonstrates to the satisfaction of the Attorney General either the existence of changed circumstances which materially affect the applicant's eligibility for asylum or extraordinary circumstances relating to the delay in filing an application within the period specified in subparagraph (B)."],[0,"(E) Applicability"],[2,"Subparagraphs (A) and (B) shall not apply to an unaccompanied alien child (as defined in section 279(g) of title 6)."],[0,"(3) Limitation on judicial review"],[1,"No court shall have jurisdiction to review any determination of the Attorney General under paragraph (2)."],[0,"(b) Conditions for granting asylum"],[0,"(1) In general"],[0,"(A) Eligibility"],[2,"The Secretary of Homeland Security or the Attorney General may grant asylum to an alien who has applied for asylum in accordance with the requirements and procedures established by the Secretary of Homeland Security or the Attorney General under this section if the Secretary of Homeland Security or the Attorney General determines that such alien is a refugee within the meaning of section 1101(a)(42)(A) of this title."],[0,"(B) Burden of proof"],[0,"(i) In general"],[3,"The burden of proof is on the applicant to establish that the applicant is a refugee, within the meaning of section 1101(a)(42)(A) of this title. To establish that the applicant is a refugee within the meaning of such section, the applicant must establish that race, religion, nationality, membership in a particular social group, or political opinion was or will be at least one central reason for persecuting the applicant."],[0,"(ii) Sustaining burden"],[3,"The testimony of the applicant may be sufficient to sustain the applicant's burden without corroboration, but only if the applicant satisfies the trier of fact that the applicant's testimony is credible, is persuasive, and refers to specific facts sufficient to demonstrate that the applicant is a refugee. In determining whether the applicant has met the applicant's burden, the trier of fact may weigh the credible testimony along with other evidence of record. Where the trier of fact determines that the applicant should provide evidence that corroborates otherwise credible testimony, such evidence must be provided unless the applicant does not have the evidence and cannot reasonably obtain the evidence."],[0,"(iii) Credibility determination"],[3,"Considering the totality of the circumstances, and all relevant factors, a trier of fact may base a credibility determination on the demeanor, candor, or responsiveness of the applicant or witness, the inherent plausibility of the applicant's or witness's account, the consistency between the applicant's or witness's written and oral statements (whenever made and whether or not under oath, and considering the circumstances under which the statements were made), the internal consistency of each such statement, the consistency of such statements with other evidence of record (including the reports of the Department of State on country conditions), and any inaccuracies or falsehoods in such statements, without regard to whether an inconsistency, inaccuracy, or falsehood goes to the heart of the applicant's claim, or any other relevant factor. There is no presumption of credibility, however, if no adverse credibility determination is explicitly made, the applicant or witness shall have a rebuttable presumption of credibility on appeal."],[0,"(2) Exceptions"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that—"],[3,"(i) the alien ordered, incited, assisted, or otherwise participated in the persecution of any person on account of race, religion, nationality, membership in a particular social group, or political opinion;"],[3,"(ii) the alien, having been convicted by a final judgment of a particularly serious crime, constitutes a danger to the community of the United States;"],[3,"(iii) there are serious reasons for believing that the alien has committed a serious nonpolitical crime outside the United States prior to the arrival of the alien in the United States;"],[3,"(iv) there are reasonable grounds for regarding the alien as a danger to the security of the United States;"],[3,"(v) the alien is described in subclause (I), (II), (III), (IV), or (VI) of section 1182(a)(3)(B)(i) of this title or section 1227(a)(4)(B) of this title (relating to terrorist activity), unless, in the case only of an alien described in subclause (IV) of section 1182(a)(3)(B)(i) of this title, the Attorney General determines, in the Attorney General's discretion, that there are not reasonable grounds for regarding the alien as a danger to the security of the United States; or"],[3,"(vi) the alien was firmly resettled in another country prior to arriving in the United States."],[0,"(B) Special rules"],[0,"(i) Conviction of aggravated felony"],[3,"For purposes of clause (ii) of subparagraph (A), an alien who has been convicted of an aggravated felony shall be considered to have been convicted of a particularly serious crime."],[0,"(ii) Offenses"],[3,"The Attorney General may designate by regulation offenses that will be considered to be a crime described in clause (ii) or (iii) of subparagraph (A)."],[0,"(C) Additional limitations"],[2,"The Attorney General may by regulation establish additional limitations and conditions, consistent with this section, under which an alien shall be ineligible for asylum under paragraph (1)."],[0,"(D) No judicial review"],[2,"There shall be no judicial review of a determination of the Attorney General under subparagraph (A)(v)."],[0,"(3) Treatment of spouse and children"],[0,"(A) In general"],[2,"A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of an alien who is granted asylum under this subsection may, if not otherwise eligible for asylum under this section, be granted the same status as the alien if accompanying, or following to join, such alien."],[0,"(B) Continued classification of certain aliens as children"],[2,"An unmarried alien who seeks to accompany, or follow to join, a parent granted asylum under this subsection, and who was under 21 years of age on the date on which such parent applied for asylum under this section, shall continue to be classified as a child for purposes of this paragraph and section 1159(b)(3) of this title, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(C) Initial jurisdiction"],[2,"An asylum officer (as defined in section 1225(b)(1)(E) of this title) shall have initial jurisdiction over any asylum application filed by an unaccompanied alien child (as defined in section 279(g) of title 6), regardless of whether filed in accordance with this section or section 1225(b) of this title."],[0,"(c) Asylum status"],[0,"(1) In general"],[1,"In the case of an alien granted asylum under subsection (b), the Attorney General—"],[2,"(A) shall not remove or return the alien to the alien's country of nationality or, in the case of a person having no nationality, the country of the alien's last habitual residence;"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with appropriate endorsement of that authorization; and"],[2,"(C) may allow the alien to travel abroad with the prior consent of the Attorney General."],[0,"(2) Termination of asylum"],[1,"Asylum granted under subsection (b) does not convey a right to remain permanently in the United States, and may be terminated if the Attorney General determines that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1158?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1158. Asylum","tname":"Aliens and Nationality","by":{"0":"44, 4"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(d)(5)","(a)(9)(B)","(d)(5)(A)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"4, 44","4":"38","5":"19"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)","(d)(2)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"head":"§1227. Deportable aliens","tname":"Aliens and Nationality","by":{"0":"4","2":"4","4":"41"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)","(b)(1)(D)"],"by":{"0":"4, 44, 44, 44"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","stext":{"head":"§1229c. Voluntary departure","paras":[[0,"(a) Certain conditions"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense under this subsection, in lieu of being subject to proceedings under section 1229a of this title or prior to the completion of such proceedings, if the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4)(B) of this title."],[0,"(2) Period"],[0,"(A) In general"],[2,"Subject to subparagraph (B), permission to depart voluntarily under this subsection shall not be valid for a period exceeding 120 days."],[0,"(B) Three-year pilot program waiver"],[2,"During the period October 1, 2000, through September 30, 2003, and subject to subparagraphs (C) and (D)(ii), the Attorney General may, in the discretion of the Attorney General for humanitarian purposes, waive application of subparagraph (A) in the case of an alien—"],[3,"(i) who was admitted to the United States as a nonimmigrant visitor (described in section 1101(a)(15)(B) of this title) under the provisions of the visa waiver pilot program established pursuant to section 1187 of this title, seeks the waiver for the purpose of continuing to receive medical treatment in the United States from a physician associated with a health care facility, and submits to the Attorney General—"],[4,"(I) a detailed diagnosis statement from the physician, which includes the treatment being sought and the expected time period the alien will be required to remain in the United States;"],[4,"(II) a statement from the health care facility containing an assurance that the alien's treatment is not being paid through any Federal or State public health assistance, that the alien's account has no outstanding balance, and that such facility will notify the Service when the alien is released or treatment is terminated; and"],[4,"(III) evidence of financial ability to support the alien's day-to-day expenses while in the United States (including the expenses of any family member described in clause (ii)) and evidence that any such alien or family member is not receiving any form of public assistance; or"],[3,"(ii) who—"],[4,"(I) is a spouse, parent, brother, sister, son, daughter, or other family member of a principal alien described in clause (i); and"],[4,"(II) entered the United States accompanying, and with the same status as, such principal alien."],[0,"(C) Waiver limitations"],[2,"(i) Waivers under subparagraph (B) may be granted only upon a request submitted by a Service district office to Service headquarters."],[2,"(ii) Not more than 300 waivers may be granted for any fiscal year for a principal alien under subparagraph (B)(i)."],[2,"(iii)(I) Except as provided in subclause (II), in the case of each principal alien described in subparagraph (B)(i) not more than one adult may be granted a waiver under subparagraph (B)(ii)."],[2,"(II) Not more than two adults may be granted a waiver under subparagraph (B)(ii) in a case in which—"],[3,"(aa) the principal alien described in subparagraph (B)(i) is a dependent under the age of 18; or"],[3,"(bb) one such adult is age 55 or older or is physically handicapped."],[0,"(D) Report to Congress; suspension of waiver authority"],[2,"(i) Not later than March 30 of each year, the Commissioner shall submit to the Congress an annual report regarding all waivers granted under subparagraph (B) during the preceding fiscal year."],[2,"(ii) Notwithstanding any other provision of law, the authority of the Attorney General under subparagraph (B) shall be suspended during any period in which an annual report under clause (i) is past due and has not been submitted."],[0,"(3) Bond"],[1,"The Attorney General may require an alien permitted to depart voluntarily under this subsection to post a voluntary departure bond, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(4) Treatment of aliens arriving in the United States"],[1,"In the case of an alien who is arriving in the United States and with respect to whom proceedings under section 1229a of this title are (or would otherwise be) initiated at the time of such alien's arrival, paragraph (1) shall not apply. Nothing in this paragraph shall be construed as preventing such an alien from withdrawing the application for admission in accordance with section 1225(a)(4) of this title."],[0,"(b) At conclusion of proceedings"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense if, at the conclusion of a proceeding under section 1229a of this title, the immigration judge enters an order granting voluntary departure in lieu of removal and finds that—"],[2,"(A) the alien has been physically present in the United States for a period of at least one year immediately preceding the date the notice to appear was served under section 1229(a) of this title;"],[2,"(B) the alien is, and has been, a person of good moral character for at least 5 years immediately preceding the alien's application for voluntary departure;"],[2,"(C) the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4) of this title; and"],[2,"(D) the alien has established by clear and convincing evidence that the alien has the means to depart the United States and intends to do so."],[0,"(2) Period"],[1,"Permission to depart voluntarily under this subsection shall not be valid for a period exceeding 60 days."],[0,"(3) Bond"],[1,"An alien permitted to depart voluntarily under this subsection shall be required to post a voluntary departure bond, in an amount necessary to ensure that the alien will depart, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(c) Aliens not eligible"],[0,"The Attorney General shall not permit an alien to depart voluntarily under this section if the alien was previously permitted to so depart after having been found inadmissible under section 1182(a)(6)(A) of this title."],[0,"(d) Civil penalty for failure to depart"],[0,"(1) In general"],[1,"Subject to paragraph (2), if an alien is permitted to depart voluntarily under this section and voluntarily fails to depart the United States within the time period specified, the alien—"],[2,"(A) shall be subject to a civil penalty of not less than $1,000 and not more than $5,000; and"],[2,"(B) shall be ineligible, for a period of 10 years, to receive any further relief under this section and sections 1229b, 1255, 1258, and 1259 of this title."],[0,"(2) Application of VAWA protections"],[1,"The restrictions on relief under paragraph (1) shall not apply to relief under section 1229b or 1255 of this title on the basis of a petition filed by a VAWA self-petitioner, or a petition filed under section 1229b(b)(2) of this title, or under section 1254(a)(3) of this title (as in effect prior to March 31, 1997), if the extreme cruelty or battery was at least one central reason for the alien's overstaying the grant of voluntary departure."],[0,"(3) Notice of penalties"],[1,"The order permitting an alien to depart voluntarily shall inform the alien of the penalties under this subsection."],[0,"(e) Additional conditions"],[0,"The Attorney General may by regulation limit eligibility for voluntary departure under this section for any class or classes of aliens. No court may review any regulation issued under this subsection."],[0,"(f) Judicial review"],[0,"No court shall have jurisdiction over an appeal from denial of a request for an order of voluntary departure under subsection (b), nor shall any court order a stay of an alien's removal pending consideration of any claim with respect to voluntary departure."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1229c. Voluntary departure","tname":"Aliens and Nationality","by":{"0":"44"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(b)(1976)","(b)","(b)(9)","(g)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"49, 49, 44, 44","2":"25, 26","4":"15, 28, 29, 15, 28, 29, 41","5":"19"}},{"t":"usc","label":"8 U.S.C. § 1254a","url":"https://www.law.cornell.edu/uscode/text/8/1254a","subs":["(b)(1)"],"by":{"0":"44, 44"}},{"t":"law","label":"Pub. L. No. 99-603","url":"https://www.govinfo.gov/link/statute/100/3359","by":{"0":"48","2":"3"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(5)"],"stext":{"head":"§202. Border, maritime, and transportation responsibilities","paras":[[0,"The Secretary shall be responsible for the following:"],[1,"(1) Preventing the entry of terrorists and the instruments of terrorism into the United States."],[1,"(2) Securing the borders, territorial waters, ports, terminals, waterways, and air, land, and sea transportation systems of the United States, including managing and coordinating those functions transferred to the Department at ports of entry."],[1,"(3) Carrying out the immigration enforcement functions vested by statute in, or performed by, the Commissioner of Immigration and Naturalization (or any officer, employee, or component of the Immigration and Naturalization Service) immediately before the date on which the transfer of functions specified under section 251 of this title takes effect."],[1,"(4) Establishing and administering rules, in accordance with section 236 of this title, governing the granting of visas or other forms of permission, including parole, to enter the United States to individuals who are not a citizen or an alien lawfully admitted for permanent residence in the United States."],[1,"(5) Establishing national immigration enforcement policies and priorities."],[1,"(6) Except as provided in part C of this subchapter, administering the customs laws of the United States."],[1,"(7) Conducting the inspection and related administrative functions of the Department of Agriculture transferred to the Secretary of Homeland Security under section 231 of this title."],[1,"(8) In carrying out the foregoing responsibilities, ensuring the speedy, orderly, and efficient flow of lawful traffic and commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/202?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§202. Border, maritime, and transportation responsibilities","tname":"Domestic Security","by":{"0":"43","1":"3, 40","2":"2, 16, 44, 52","4":"4, 28, 39"}},{"t":"usc","label":"49 U.S.C. § 30301","url":"https://www.law.cornell.edu/uscode/text/49/30301","by":{"0":"43","1":"26, 29","2":"45"}},{"t":"reg","label":"8 C.F.R. pt. 274","url":"https://www.ecfr.gov/current/title-8/part-274","by":{"0":"5, 44","2":"6, 35, 46","3":"3,46","4":"5, 38, 40"}},{"t":"reg","label":"43 Fed. Reg. 29,526","url":"https://www.govinfo.gov/link/fr/43/29526","by":{"0":"49"}},{"t":"reg","label":"84 Fed. Reg. 33,829","url":"https://www.govinfo.gov/link/fr/84/33829","by":{"0":"40"}},{"t":"law","label":"Pub. L. No. 114-113","url":"https://www.govinfo.gov/link/plaw/114/public/113","by":{"1":"32","4":"28"}},{"t":"law","label":"Dep’t of State Authorization Act, Pub. L. No. 98-164","url":"https://www.govinfo.gov/link/statute/97/1017","by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"1":"29, 31","2":"49"}},{"t":"reg","label":"8 C.F.R. § 1.3","url":"https://www.ecfr.gov/current/title-8/section-1.3","subs":["(a)(4)(vi)","(a)(4)"],"by":{"1":"4, 27","2":"6","3":"47","4":"6, 38"}},{"t":"reg","label":"28 C.F.R. § 1100.35","url":"https://www.ecfr.gov/current/title-28/section-1100.35","subs":["(b)(2)"],"by":{"1":"4, 26"}},{"t":"reg","label":"46 Fed. Reg. 25,080","url":"https://www.govinfo.gov/link/fr/46/25080","by":{"1":"26"}},{"t":"reg","label":"55 Fed. Reg. 6058","url":"https://www.govinfo.gov/link/fr/55/6058","by":{"1":"28"}},{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"op":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Burlington Truck Lines, Inc. v. United States","cite":"371 U.S. 156","y":1962,"id":"1962/27","sc":1,"op":1,"sum":"The judgment is reversed and the case is remanded to the District Court with instructions to set aside the Commission's order and remand the case to the Commission for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27","4":"48","5":"3"}},{"t":"case","label":"Casa De Maryland v. U.S. Dep’t of Homeland Sec.","cite":"284 F. Supp. 3d 758","y":2018,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/284/758/","op":1,"by":{"2":"13"}},{"t":"case","label":"Citizens to Preserve Overton Park, Inc. v. Volpe","cite":"401 U.S. 402","y":1971,"id":"1970/1066","sc":1,"op":4,"sum":"Rejecting “litigation affdavits” from agency offcials as “merely `post hoc' rationalizations”.","sumSrc":"opinion","by":{"2":"18, 55","3":"23","4":"24, 53","5":"4"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"FCC v. Fox Television Stations","cite":"566 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"op":3,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"2":"41","3":"25,40","4":"26, 35","5":"16"}},{"t":"case","label":"Fed. Election Comm’n v. Akins","cite":"524 U.S. 11","y":1998,"id":"1997/96-1590","sc":1,"sum":"The Court held that voters seeking information, to which they believe FECA entitles them, have standing to challenge the FEC's decision not to bring an enforcement action. Because FECA seeks to address the voters' injury, the failure to obtain relevant information, Justice Breyer concluded that the voters had prudential standing.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Fed. Power Comm’n v. Texaco Inc.","cite":"417 U.S. 380","y":1974,"id":"1973/72-1490","sc":1,"op":1,"sum":"Following its notice of proposed rulemaking \"propos[ing] prospectively to exempt from regulation under the Natural Gas Act all existing and all future jurisdictional sales made by small producers...,\" and the filing of comments and informal conferences, the Federal Power Commission (FPC) issued Order No. 428, which exempted all existing and future sales by \"small producers\" from direct rate regulation, and provided …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"case","label":"Int’l Union, United Mine Workers of Am. v. U.S. Dep’t of Labor","cite":"358 F.3d 40","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/358/40/","by":{"2":"53"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"ar":1,"sum":"The Court held that the policy used to determine whether a resident alien is able to ask for relief from deportation under a repealed portion of immigration laws is “arbitrary and capricious” under the Administrative Procedure Act, 5 U.S.C. § 706(2)(A).","sumSrc":"Oyez","by":{"2":"27, 31, 39","3":"28","4":"27","5":"12"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"ar":1,"by":{"2":"18","3":"26","4":"18, 19, 28"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","by":{"2":"18"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"op":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"2":"20, 22, 44","3":"28","4":"20","5":"8, 21"}},{"t":"case","label":"Michigan v. E.P.A.","cite":"135 S. Ct. 2699","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2699/","sc":1,"by":{"2":"27","4":"26, 29, 34, 35, 36","5":"17"}},{"t":"case","label":"Neil v. Biggers","cite":"409 U.S. 188","y":1972,"id":"1972/71-586","sc":1,"op":1,"sum":"No. In a 5-3 decision Justice Lewis F. Powell wrote the majority opinion reversing in part and remanding. The entire court joined in the first part of the opinion, holding that affirming by an equally divided court did not constitute an “actual adjudication” of the issue. The habeas corpus proceeding could continue.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Negusie v. Holder","cite":"555 U.S. 511","y":2009,"id":"2008/07-499","sc":1,"sum":"The Court held that the Board of Immigration Appeals (BIA) incorrectly interpreted provisions of the Immigration and Nationality Act (INA) from a mistaken legal premise.","sumSrc":"Oyez","by":{"2":"34, 44"}},{"t":"case","label":"Organized Vill. of Kake v. U.S. Dep’t of Agric.","cite":"795 F.3d 956","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/795/956/","sum":"Rejecting litigation risk rationale.","sumSrc":"brief:2","by":{"2":"53"}},{"t":"case","label":"OSG Bulk Ships, Inc. v. United States","cite":"132 F.3d 808","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/132/808/","by":{"2":"23"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"op":2,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31, 37","4":"48"}},{"t":"case","label":"Weyerhauser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17, 20","3":"16,23,24","4":"17"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"2":"18"}},{"t":"usc","label":"8 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/8/1151","by":{"2":"4, 45"}},{"t":"usc","label":"8 U.S.C. § 1154","url":"https://www.law.cornell.edu/uscode/text/8/1154","stext":{"head":"§1154. Procedure for granting immigrant status","paras":[[0,"(a) Petitioning procedure"],[0,"(1)(A)(i) Except as provided in clause (viii), any citizen of the United States claiming that an alien is entitled to classification by reason of a relationship described in paragraph (1), (3), or (4) of section 1153(a) of this title or to an immediate relative status under section 1151(b)(2)(A)(i) of this title may file a petition with the Attorney General for such classification."],[0,"(ii) An alien spouse described in the second sentence of section 1151(b)(2)(A)(i) of this title also may file a petition with the Attorney General under this subparagraph for classification of the alien (and the alien's children) under such section."],[0,"(iii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the United States citizen was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this subclause is an alien—"],[1,"(aa)(AA) who is the spouse of a citizen of the United States;"],[1,"(BB) who believed that he or she had married a citizen of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such citizen of the United States; or"],[1,"(CC) who was a bona fide spouse of a United States citizen within the past 2 years and—"],[2,"(aaa) whose spouse died within the past 2 years;"],[2,"(bbb) whose spouse lost or renounced citizenship status within the past 2 years related to an incident of domestic violence; or"],[2,"(ccc) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the United States citizen spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title or who would have been so classified but for the bigamy of the citizen of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iv) An alien who is the child of a citizen of the United States, or who was a child of a United States citizen parent who within the past 2 years lost or renounced citizenship status related to an incident of domestic violence, and who is a person of good moral character, who is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title, and who resides, or has resided in the past, with the citizen parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's citizen parent. For purposes of this clause, residence includes any period of visitation."],[0,"(v) An alien who—"],[1,"(I) is the spouse, intended spouse, or child living abroad of a citizen who—"],[2,"(aa) is an employee of the United States Government;"],[2,"(bb) is a member of the uniformed services (as defined in section 101(a) of title 10); or"],[2,"(cc) has subjected the alien or the alien's child to battery or extreme cruelty in the United States; and"],[1,"(II) is eligible to file a petition under clause (iii) or (iv),"],[0,"shall file such petition with the Attorney General under the procedures that apply to self-petitioners under clause (iii) or (iv), as applicable."],[0,"(vi) For the purposes of any petition filed under clause (iii) or (iv), the denaturalization, loss or renunciation of citizenship, death of the abuser, divorce, or changes to the abuser's citizenship status after filing of the petition shall not adversely affect the approval of the petition, and for approved petitions shall not preclude the classification of the eligible self-petitioning spouse or child as an immediate relative or affect the alien's ability to adjust status under subsections (a) and (c) of section 1255 of this title or obtain status as a lawful permanent resident based on the approved self-petition under such clauses."],[0,"(vii) An alien may file a petition with the Secretary of Homeland Security under this subparagraph for classification of the alien under section 1151(b)(2)(A)(i) of this title if the alien—"],[1,"(I) is the parent of a citizen of the United States or was a parent of a citizen of the United States who, within the past 2 years, lost or renounced citizenship status related to an incident of domestic violence or died;"],[1,"(II) is a person of good moral character;"],[1,"(III) is eligible to be classified as an immediate relative under section 1151(b)(2)(A)(i) of this title;"],[1,"(IV) resides, or has resided, with the citizen daughter or son; and"],[1,"(V) demonstrates that the alien has been battered or subject to extreme cruelty by the citizen daughter or son."],[0,"(viii)(I) Clause (i) shall not apply to a citizen of the United States who has been convicted of a specified offense against a minor, unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that the citizen poses no risk to the alien with respect to whom a petition described in clause (i) is filed."],[0,"(II) For purposes of subclause (I), the term \"specified offense against a minor\" is defined as in section 20911 of title 34."],[0,"(B)(i)(I) Except as provided in subclause (II), any alien lawfully admitted for permanent residence claiming that an alien is entitled to a classification by reason of the relationship described in section 1153(a)(2) of this title may file a petition with the Attorney General for such classification."],[0,"(I) 1 Subclause (I) shall not apply in the case of an alien lawfully admitted for permanent residence who has been convicted of a specified offense against a minor (as defined in subparagraph (A)(viii)(II)), unless the Secretary of Homeland Security, in the Secretary's sole and unreviewable discretion, determines that such person poses no risk to the alien with respect to whom a petition described in subclause (I) is filed."],[0,"(ii)(I) An alien who is described in subclause (II) may file a petition with the Attorney General under this clause for classification of the alien (and any child of the alien) if such a child has not been classified under clause (iii) of section 1153(a)(2)(A) of this title and if the alien demonstrates to the Attorney General that—"],[1,"(aa) the marriage or the intent to marry the lawful permanent resident was entered into in good faith by the alien; and"],[1,"(bb) during the marriage or relationship intended by the alien to be legally a marriage, the alien or a child of the alien has been battered or has been the subject of extreme cruelty perpetrated by the alien's spouse or intended spouse."],[0,"(II) For purposes of subclause (I), an alien described in this paragraph is an alien—"],[1,"(aa)(AA) who is the spouse of a lawful permanent resident of the United States; or"],[1,"(BB) who believed that he or she had married a lawful permanent resident of the United States and with whom a marriage ceremony was actually performed and who otherwise meets any applicable requirements under this chapter to establish the existence of and bona fides of a marriage, but whose marriage is not legitimate solely because of the bigamy of such lawful permanent resident of the United States; or"],[1,"(CC) who was a bona fide spouse of a lawful permanent resident within the past 2 years and—"],[2,"(aaa) whose spouse lost status within the past 2 years due to an incident of domestic violence; or"],[2,"(bbb) who demonstrates a connection between the legal termination of the marriage within the past 2 years and battering or extreme cruelty by the lawful permanent resident spouse;"],[1,"(bb) who is a person of good moral character;"],[1,"(cc) who is eligible to be classified as a spouse of an alien lawfully admitted for permanent residence under section 1153(a)(2)(A) of this title or who would have been so classified but for the bigamy of the lawful permanent resident of the United States that the alien intended to marry; and"],[1,"(dd) who has resided with the alien's spouse or intended spouse."],[0,"(iii) An alien who is the child of an alien lawfully admitted for permanent residence, or who was the child of a lawful permanent resident who within the past 2 years lost lawful permanent resident status due to an incident of domestic violence, and who is a person of good moral character, who is eligible for classification under section 1153(a)(2)(A) of this title, and who resides, or has resided in the past, with the alien's permanent resident alien parent may file a petition with the Attorney General under this subparagraph for classification of the alien (and any child of the alien) under such section if the alien demonstrates to the Attorney General that the alien has been battered by or has been the subject of extreme cruelty perpetrated by the alien's permanent resident parent."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1154?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1154. Procedure for granting immigrant status","tname":"Aliens and Nationality","by":{"2":"4, 45"}},{"t":"usc","label":"8 U.S.C. § 1181-88","url":"https://www.law.cornell.edu/uscode/text/8/1181-88","by":{"2":"2"}},{"t":"usc","label":"8 U.S.C. § 1226-29c","url":"https://www.law.cornell.edu/uscode/text/8/1226-29c","by":{"2":"2"}},{"t":"usc","label":"8 U.S.C. § 1324a","url":"https://www.law.cornell.edu/uscode/text/8/1324a","subs":["(h)(3)"],"stext":{"head":"§1324a. Unlawful employment of aliens","paras":[[0,"(a) Making employment of unauthorized aliens unlawful"],[0,"(1) In general"],[1,"It is unlawful for a person or other entity—"],[2,"(A) to hire, or to recruit or refer for a fee, for employment in the United States an alien knowing the alien is an unauthorized alien (as defined in subsection (h)(3)) with respect to such employment, or"],[2,"(B)(i) to hire for employment in the United States an individual without complying with the requirements of subsection (b) or (ii) if the person or entity is an agricultural association, agricultural employer, or farm labor contractor (as defined in section 1802 of title 29), to hire, or to recruit or refer for a fee, for employment in the United States an individual without complying with the requirements of subsection (b)."],[0,"(2) Continuing employment"],[1,"It is unlawful for a person or other entity, after hiring an alien for employment in accordance with paragraph (1), to continue to employ the alien in the United States knowing the alien is (or has become) an unauthorized alien with respect to such employment."],[0,"(3) Defense"],[1,"A person or entity that establishes that it has complied in good faith with the requirements of subsection (b) with respect to the hiring, recruiting, or referral for employment of an alien in the United States has established an affirmative defense that the person or entity has not violated paragraph (1)(A) with respect to such hiring, recruiting, or referral."],[0,"(4) Use of labor through contract"],[1,"For purposes of this section, a person or other entity who uses a contract, subcontract, or exchange, entered into, renegotiated, or extended after November 6, 1986, to obtain the labor of an alien in the United States knowing that the alien is an unauthorized alien (as defined in subsection (h)(3)) with respect to performing such labor, shall be considered to have hired the alien for employment in the United States in violation of paragraph (1)(A)."],[0,"(5) Use of State employment agency documentation"],[1,"For purposes of paragraphs (1)(B) and (3), a person or entity shall be deemed to have complied with the requirements of subsection (b) with respect to the hiring of an individual who was referred for such employment by a State employment agency (as defined by the Attorney General), if the person or entity has and retains (for the period and in the manner described in subsection (b)(3)) appropriate documentation of such referral by that agency, which documentation certifies that the agency has complied with the procedures specified in subsection (b) with respect to the individual's referral."],[0,"(6) Treatment of documentation for certain employees"],[0,"(A) In general"],[2,"For purposes of this section, if—"],[3,"(i) an individual is a member of a collective-bargaining unit and is employed, under a collective bargaining agreement entered into between one or more employee organizations and an association of two or more employers, by an employer that is a member of such association, and"],[3,"(ii) within the period specified in subparagraph (B), another employer that is a member of the association (or an agent of such association on behalf of the employer) has complied with the requirements of subsection (b) with respect to the employment of the individual,"],[2,"the subsequent employer shall be deemed to have complied with the requirements of subsection (b) with respect to the hiring of the employee and shall not be liable for civil penalties described in subsection (e)(5)."],[0,"(B) Period"],[2,"The period described in this subparagraph is 3 years, or, if less, the period of time that the individual is authorized to be employed in the United States."],[0,"(C) Liability"],[0,"(i) In general"],[3,"If any employer that is a member of an association hires for employment in the United States an individual and relies upon the provisions of subparagraph (A) to comply with the requirements of subsection (b) and the individual is an alien not authorized to work in the United States, then for the purposes of paragraph (1)(A), subject to clause (ii), the employer shall be presumed to have known at the time of hiring or afterward that the individual was an alien not authorized to work in the United States."],[0,"(ii) Rebuttal of presumption"],[3,"The presumption established by clause (i) may be rebutted by the employer only through the presentation of clear and convincing evidence that the employer did not know (and could not reasonably have known) that the individual at the time of hiring or afterward was an alien not authorized to work in the United States."],[0,"(iii) Exception"],[3,"Clause (i) shall not apply in any prosecution under subsection (f)(1)."],[0,"(7) Application to Federal Government"],[1,"For purposes of this section, the term \"entity\" includes an entity in any branch of the Federal Government."],[0,"(b) Employment verification system"],[0,"The requirements referred to in paragraphs (1)(B) and (3) of subsection (a) are, in the case of a person or other entity hiring, recruiting, or referring an individual for employment in the United States, the requirements specified in the following three paragraphs:"],[0,"(1) Attestation after examination of documentation"],[0,"(A) In general"],[2,"The person or entity must attest, under penalty of perjury and on a form designated or established by the Attorney General by regulation, that it has verified that the individual is not an unauthorized alien by examining—"],[3,"(i) a document described in subparagraph (B), or"],[3,"(ii) a document described in subparagraph (C) and a document described in subparagraph (D)."],[2,"Such attestation may be manifested by either a hand-written or an electronic signature. A person or entity has complied with the requirement of this paragraph with respect to examination of a document if the document reasonably appears on its face to be genuine. If an individual provides a document or combination of documents that reasonably appears on its face to be genuine and that is sufficient to meet the requirements of the first sentence of this paragraph, nothing in this paragraph shall be construed as requiring the person or entity to solicit the production of any other document or as requiring the individual to produce such another document."],[0,"(B) Documents establishing both employment authorization and identity"],[2,"A document described in this subparagraph is an individual's—"],[3,"(i) United States passport; 1"],[3,"(ii) resident alien card, alien registration card, or other document designated by the Attorney General, if the document—"],[4,"(I) contains a photograph of the individual and such other personal identifying information relating to the individual as the Attorney General finds, by regulation, sufficient for purposes of this subsection,"],[4,"(II) is evidence of authorization of employment in the United States, and"],[4,"(III) contains security features to make it resistant to tampering, counterfeiting, and fraudulent use."],[0,"(C) Documents evidencing employment authorization"],[2,"A document described in this subparagraph is an individual's—"],[3,"(i) social security account number card (other than such a card which specifies on the face that the issuance of the card does not authorize employment in the United States); or"],[3,"(ii) other documentation evidencing authorization of employment in the United States which the Attorney General finds, by regulation, to be acceptable for purposes of this section."],[0,"(D) Documents establishing identity of individual"],[2,"A document described in this subparagraph is an individual's—"],[3,"(i) driver's license or similar document issued for the purpose of identification by a State, if it contains a photograph of the individual or such other personal identifying information relating to the individual as the Attorney General finds, by regulation, sufficient for purposes of this section; or"],[3,"(ii) in the case of individuals under 16 years of age or in a State which does not provide for issuance of an identification document (other than a driver's license) referred to in clause (i), documentation of personal identity of such other type as the Attorney General finds, by regulation, provides a reliable means of identification."],[0,"(E) Authority to prohibit use of certain documents"],[2,"If the Attorney General finds, by regulation, that any document described in subparagraph (B), (C), or (D) as establishing employment authorization or identity does not reliably establish such authorization or identity or is being used fraudulently to an unacceptable degree, the Attorney General may prohibit or place conditions on its use for purposes of this subsection."],[0,"(2) Individual attestation of employment authorization"],[1,"The individual must attest, under penalty of perjury on the form designated or established for purposes of paragraph (1), that the individual is a citizen or national of the United States, an alien lawfully admitted for permanent residence, or an alien who is authorized under this chapter or by the Attorney General to be hired, recruited, or referred for such employment. Such attestation may be manifested by either a hand-written or an electronic signature."],[0,"(3) Retention of verification form"],[1,"After completion of such form in accordance with paragraphs (1) and (2), the person or entity must retain a paper, microfiche, microfilm, or electronic version of the form and make it available for inspection by officers of the Service, the Special Counsel for Immigration-Related Unfair Employment Practices, or the Department of Labor during a period beginning on the date of the hiring, recruiting, or referral of the individual and ending—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1324a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1324a. Unlawful employment of aliens","tname":"Aliens and Nationality","by":{"2":"17","4":"5, 41","5":"19, 19"}},{"t":"reg","label":"8 C.F.R. § 109.1","url":"https://www.ecfr.gov/current/title-8/section-109.1","subs":["(b)(7)","(b)(6)"],"by":{"2":"6","4":"5, 40, 41"}},{"t":"case","label":"Arizona Dream Act Coal. v. Brewer","cite":"855 F.3d 957","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/855/957/","by":{"3":"4"}},{"t":"case","label":"Arpaio v. Obama","cite":"797 F.3d 11","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/797/11/","by":{"3":"6","4":"31"}},{"t":"case","label":"AT&T Info. Sys., Inc. v. General Servs. Admin.","cite":"810 F.2d 1233","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/810/1233/","by":{"3":"20"}},{"t":"case","label":"Bowen v. Michigan Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":2,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22"}},{"t":"case","label":"Camp v. Pitts","cite":"411 U.S. 138","y":1973,"id":"1972/72-864","sc":1,"op":3,"ar":2,"sum":"The appropriate standard for judicial review of a decision by the Comptroller of the Currency denying a national bank charter is whether his adjudication was \"arbitrary, capricious, an abuse of discretion or otherwise not in accordance with law.\" The District Court is to review the administrative record already in existence, supplemented if necessary by affidavits or testimony amplifying the reason for the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20","5":"4"}},{"t":"case","label":"Crowley Caribbean Transp., Inc. v. Pena","cite":"37 F.3d 671","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/37/671/","by":{"3":"29","4":"20"}},{"t":"case","label":"Department of Transp. v. Association of Am. R.R.","cite":"135 S. Ct. 1225","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1225/","sc":1,"by":{"3":"26"}},{"t":"case","label":"Food Mktg. Inst. v. Interstate Commerce Comm’n","cite":"587 F.2d 1285","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/587/1285/","op":1,"by":{"3":"22"}},{"t":"case","label":"Jama v. Immigration & Customs Enf’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"3":"44"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"sum":"This action was authorized by the Act of June 21, 1941, 22 U. S. C. § 223, and the proclamations and regulations issued thereunder, notwithstanding the War Brides Act of December 28, 1945, 8 U. S. C. § 232 et seq.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"44","4":"43"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Lennon v. INS","cite":"527 F.2d 187","y":1975,"url":"https://www.courtlistener.com/c/F.2d/527/187/","by":{"3":"46"}},{"t":"case","label":"Montana Air Chapter No. 29, Ass’n of Civilian Technicians, Inc. v. Federal Labor Relations Auth.","cite":"898 F.2d 753","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/898/753/","by":{"3":"29"}},{"t":"case","label":"NAACP v. Trump","cite":"321 F. Supp. 3d 143","y":2018,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/321/143/","op":5,"by":{"3":"12,13"}},{"t":"case","label":"Staub v. Proctor Hosp.","cite":"562 U.S. 411","y":2011,"id":"2010/09-400","sc":1,"sum":"The Court held that an employer may be found liable for the discriminatory acts of supervisors, who do not themselves make employment decisions but do influence the employment decision-makers.","sumSrc":"Oyez","by":{"3":"56"}},{"t":"case","label":"Walter O. Boswell Mem’l Hosp. v. Heckler","cite":"749 F.2d 788","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/749/788/","by":{"3":"51","4":"36"}},{"t":"case","label":"Winter v. Natural Resources Def. Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"3":"30"}},{"t":"reg","label":"44 Fed. Reg. 10,369","url":"https://www.govinfo.gov/link/fr/44/10369","by":{"3":"47"}},{"t":"reg","label":"46 Fed. Reg. 25,079","url":"https://www.govinfo.gov/link/fr/46/25079","by":{"3":"47"}},{"t":"case","label":"Berger v. United States","cite":"295 U.S. 78","y":1935,"id":"scdb/1934-109","sc":1,"by":{"4":"43"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"op":2,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"4":"38"}},{"t":"case","label":"Capitol Sprinkler Inspection, Inc. v. Guest Servs., Inc.","cite":"630 F.3d 217","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/630/217/","by":{"4":"25"}},{"t":"case","label":"Citizens for Responsibility & Ethics in Washington v. U.S. Dep’t of Justice","cite":"922 F.3d 480","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/922/480/","by":{"4":"32"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"sum":"Respondents, the defendants in a District Court suit instituted by petitioner law firm on behalf of a client, filed a motion to dismiss the complaint as having no basis in fact and a motion for sanctions under Federal Rule of Civil Procedure 11 on the ground that the firm had not made sufficient prefiling inquiries to support the complaint's allegations. Rule 11-after specifying, interalia, that an attorney's …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"48"}},{"t":"case","label":"Crane v. Johnson","cite":"783 F.3d 244","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/783/244/","by":{"4":"31"}},{"t":"case","label":"Dalton v. Specter","cite":"511 U.S. 462","y":1994,"id":"1993/93-289","sc":1,"sum":"Judicial review is not available for respondents' claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"32"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"op":1,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"4":"42"}},{"t":"case","label":"E. Bay Sanctuary Covenant v. Trump","cite":"354 F. Supp. 3d 1094","y":2018,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/354/1094/","by":{"4":"54"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"op":2,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"4":"23"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"136 S. Ct. 1969","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"4":"37"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"op":3,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"22, 40"}},{"t":"case","label":"M.G.U. v. Nielsen","cite":"325 F. Supp. 3d 111","y":2018,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/325/111/","op":35,"ar":22,"by":{"4":"54"}},{"t":"case","label":"Mass. Trs. of E. Gas & Fuel Assocs. v. United States","cite":"377 U.S. 235","y":1964,"id":"1963/137","sc":1,"sum":"Petitioners chartered ships from the Maritime Commission under a contract providing for payment which included a share of excess profits under a sliding scale of 50 to 90 percent. Section 5 (b) of the Merchant Ship Sales Act of 1946 directed the Commission to fix charter hire at rates which \"shall not be less than 15 per centum per annum of the statutory sales price,\" and shall be consistent with the Act's policy to …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"51, 53, 58"}},{"t":"case","label":"Mingo Logan Coal Co. v. EPA","cite":"829 F.3d 710","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/829/710/","by":{"4":"34, 57"}},{"t":"case","label":"Moses H. Cone Mem’l Hosp. v. Mercury Constr. Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"25"}},{"t":"case","label":"Ms. L. v. ICE","cite":"310 F. Supp. 3d 1133","y":2018,"court":"S.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/310/1133/","by":{"4":"54"}},{"t":"case","label":"Red Lion Broad. Co. v. FCC","cite":"395 U.S. 367","y":1969,"id":"1968/2","sc":1,"sum":"The Court held that the fairness doctrine was consistent with the First Amendment.","sumSrc":"Oyez","by":{"4":"41"}},{"t":"case","label":"Rucho v. Common Cause","cite":"139 S. Ct. 2484","y":2019,"id":"2018/18-422","sc":1,"sum":"Partisan gerrymandering claims present political questions beyond the reach of the federal courts.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"45"}},{"t":"case","label":"Rutledge v. United States","cite":"517 U.S. 292","y":1996,"id":"1995/94-8769","sc":1,"sum":"Announced by Justice John Paul Stevens, the Court ruled one of the two sentences must be dropped. Both of the offenses were based on the same criminal act. Justice Stevens wrote, \"A guilty verdict on a (continuing criminal enterprise) charge necessarily includes a finding that the defendant also participated in a conspiracy.\".","sumSrc":"Oyez","by":{"4":"33"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","id":"2017/15-1498","sc":1,"op":10,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"4":"43, 45"}},{"t":"case","label":"Shieldalloy Metallurgical Corp. v. Nuclear Regulatory Comm’n","cite":"624 F.3d 489","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/624/489/","by":{"4":"37"}},{"t":"case","label":"SPV-LS, LLC v. Transamerica Life Ins. Co.","cite":"912 F.3d 1106","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/912/1106/","by":{"4":"25"}},{"t":"case","label":"Texas v. United States","cite":"136 S. Ct. 2271","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/2271/","sc":1,"by":{"4":"8"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"sum":"The Clean Water Act prohibits any discharge of dredged or fill materials into \"navigable waters\"-defined as the \"waters of the United States\"unless authorized by a permit issued by the Army Corps of Engineers (Corps). Construing the Act to cover all \"freshwater wetlands\" that are adjacent to other covered waters, the Corps issued a regulation defining such wetlands as \"those areas that are inundated or saturated by …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"42"}},{"t":"case","label":"White Stallion Energy Ctr., LLC v. EPA","cite":"748 F.3d 1222","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/748/1222/","by":{"4":"36"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"4":"42"}},{"t":"usc","label":"5 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/5/1151","subs":["(b)(2)(A)(i)"],"by":{"4":"51"}},{"t":"usc","label":"8 U.S.C. § 1427","url":"https://www.law.cornell.edu/uscode/text/8/1427","by":{"4":"51"}},{"t":"usc","label":"8 U.S.C. § 1611","url":"https://www.law.cornell.edu/uscode/text/8/1611","subs":["(b)(2)"],"stext":{"head":"§1611. Aliens who are not qualified aliens ineligible for Federal public benefits","paras":[[0,"(a) In general"],[0,"Notwithstanding any other provision of law and except as provided in subsection (b), an alien who is not a qualified alien (as defined in section 1641 of this title) is not eligible for any Federal public benefit (as defined in subsection (c))."],[0,"(b) Exceptions"],[0,"(1) Subsection (a) shall not apply with respect to the following Federal public benefits:"],[1,"(A) Medical assistance under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] (or any successor program to such title) for care and services that are necessary for the treatment of an emergency medical condition (as defined in section 1903(v)(3) of such Act [42 U.S.C. 1396b(v)(3)]) of the alien involved and are not related to an organ transplant procedure, if the alien involved otherwise meets the eligibility requirements for medical assistance under the State plan approved under such title (other than the requirement of the receipt of aid or assistance under title IV of such Act [42 U.S.C. 601 et seq.], supplemental security income benefits under title XVI of such Act [42 U.S.C. 1381 et seq.], or a State supplementary payment)."],[1,"(B) Short-term, non-cash, in-kind emergency disaster relief."],[1,"(C) Public health assistance (not including any assistance under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.]) for immunizations with respect to immunizable diseases and for testing and treatment of symptoms of communicable diseases whether or not such symptoms are caused by a communicable disease."],[1,"(D) Programs, services, or assistance (such as soup kitchens, crisis counseling and intervention, and short-term shelter) specified by the Attorney General, in the Attorney General's sole and unreviewable discretion after consultation with appropriate Federal agencies and departments, which (i) deliver in-kind services at the community level, including through public or private nonprofit agencies; (ii) do not condition the provision of assistance, the amount of assistance provided, or the cost of assistance provided on the individual recipient's income or resources; and (iii) are necessary for the protection of life or safety."],[1,"(E) Programs for housing or community development assistance or financial assistance administered by the Secretary of Housing and Urban Development, any program under title V of the Housing Act of 1949 [42 U.S.C. 1471 et seq.], or any assistance under section 1926c of title 7, to the extent that the alien is receiving such a benefit on August 22, 1996."],[0,"(2) Subsection (a) shall not apply to any benefit payable under title II of the Social Security Act [42 U.S.C. 401 et seq.] to an alien who is lawfully present in the United States as determined by the Attorney General, to any benefit if nonpayment of such benefit would contravene an international agreement described in section 233 of the Social Security Act [42 U.S.C. 433], to any benefit if nonpayment would be contrary to section 202(t) of the Social Security Act [42 U.S.C. 402(t)], or to any benefit payable under title II of the Social Security Act to which entitlement is based on an application filed in or before August 1996."],[0,"(3) Subsection (a) shall not apply to any benefit payable under title XVIII of the Social Security Act [42 U.S.C. 1395 et seq.] (relating to the medicare program) to an alien who is lawfully present in the United States as determined by the Attorney General and, with respect to benefits payable under part A of such title [42 U.S.C. 1395c et seq.], who was authorized to be employed with respect to any wages attributable to employment which are counted for purposes of eligibility for such benefits."],[0,"(4) Subsection (a) shall not apply to any benefit payable under the Railroad Retirement Act of 1974 [45 U.S.C. 231 et seq.] or the Railroad Unemployment Insurance Act [45 U.S.C. 351 et seq.] to an alien who is lawfully present in the United States as determined by the Attorney General or to an alien residing outside the United States."],[0,"(5) Subsection (a) shall not apply to eligibility for benefits for the program defined in section 1612(a)(3)(A) of this title (relating to the supplemental security income program), or to eligibility for benefits under any other program that is based on eligibility for benefits under the program so defined, for an alien who was receiving such benefits on August 22, 1996."],[0,"(c) \"Federal public benefit\" defined"],[0,"(1) Except as provided in paragraph (2), for purposes of this chapter the term \"Federal public benefit\" means—"],[1,"(A) any grant, contract, loan, professional license, or commercial license provided by an agency of the United States or by appropriated funds of the United States; and"],[1,"(B) any retirement, welfare, health, disability, public or assisted housing, postsecondary education, food assistance, unemployment benefit, or any other similar benefit for which payments or assistance are provided to an individual, household, or family eligibility unit by an agency of the United States or by appropriated funds of the United States."],[0,"(2) Such term shall not apply—"],[1,"(A) to any contract, professional license, or commercial license for a nonimmigrant whose visa for entry is related to such employment in the United States, or to a citizen of a freely associated state, if section 141 of the applicable compact of free association approved in Public Law 99–239 or 99–658 (or a successor provision) is in effect;"],[1,"(B) with respect to benefits for an alien who as a work authorized nonimmigrant or as an alien lawfully admitted for permanent residence under the Immigration and Nationality Act [8 U.S.C. 1101 et seq.] qualified for such benefits and for whom the United States under reciprocal treaty agreements is required to pay benefits, as determined by the Attorney General, after consultation with the Secretary of State; or"],[1,"(C) to the issuance of a professional license to, or the renewal of a professional license by, a foreign national not physically present in the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1611?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1611. Aliens who are not qualified aliens ineligible for Federal public benefits","tname":"Aliens and Nationality","by":{"4":"6"}},{"t":"law","label":"Pub. L. No. 110-161","url":"https://www.govinfo.gov/link/plaw/110/public/161","by":{"4":"28"}},{"t":"law","label":"Pub. L. No. 107-56","url":"https://www.govinfo.gov/link/plaw/107/public/56","by":{"4":"41"}},{"t":"reg","label":"8 C.F.R. § 212.5","url":"https://www.ecfr.gov/current/title-8/section-212.5","by":{"4":"6"}},{"t":"reg","label":"42 C.F.R. § 417.422","url":"https://www.ecfr.gov/current/title-42/section-417.422","subs":["(h)"],"by":{"4":"6, 38"}},{"t":"case","label":"FCC v. National Citizens Comm. for Broadcasting","cite":"436 U.S. 775","y":1978,"id":"1977/76-1471","sc":1,"sum":"The challenged regulations are valid in their entirety.","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"21"}},{"t":"case","label":"NLRB v. Wyman-Gordon Co.","cite":"394 U.S. 759","y":1969,"id":"1968/463","sc":1,"op":2,"sum":"The judgment of the Court of Appeals is reversed and the case is remanded to the District Court with directions to reinstate its judgment. Pp. 761-775. 397 F. 2d 394, reversed and remanded. MR. JUSTICE FORTAS, joined by THE CHIEF JUSTICE, MR. JUSTICE STEWART, and MR. JUSTICE WHITE, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"6"}},{"t":"case","label":"National Treasury Emps. Union v. Von Raab","cite":"489 U.S. 656","y":1989,"id":"1988/86-1879","sc":1,"sum":"The Court held that the \"substantial interests\" of the government in stifling the drug trade justified \"departure from the ordinary warrant and probable cause requirements\" associated with searches.","sumSrc":"Oyez","by":{"5":"5"}},{"t":"case","label":"PDK Labs., Inc. v. DEA","cite":"362 F.3d 786","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/362/786/","by":{"5":"6"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"5":"19"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)","(13)"],"stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§551. Definitions","tname":"Government Organization and Employees","by":{"5":"4, 4, 5"}},{"t":"law","label":"Pub. L. No. 111-83","url":"https://www.govinfo.gov/link/plaw/111/public/83","by":{"5":"18"}}]};